 24→        function_name: "dodo-webhook",
 25→        error_type: "MISSING_CONFIG",
 26→        severity: "critical",
 27→        error_message: "DODO_PAYMENTS_API_KEY is not configured",
 28→      });
 29→      return new Response("Server misconfigured", { status: 500, headers: corsHeaders });
 30→    }
 31→    if (!WEBHOOK_KEY) {
 32→      console.error("DODO_PAYMENTS_WEBHOOK_KEY/SECRET is not configured");
 33→      await logSystemError({
 34→        function_name: "dodo-webhook",
 35→        error_type: "MISSING_CONFIG",
 36→        severity: "critical",
 37→        error_message: "DODO_PAYMENTS_WEBHOOK_KEY/SECRET is not configured",
 38→      });
 39→      return new Response("Server misconfigured", { status: 500, headers: corsHeaders });
 40→    }
 41→
 42→    const rawBody = await req.text();
 43→    const webhookHeaders = {
 44→      "webhook-id": req.headers.get("webhook-id") || "",
 45→      "webhook-signature": req.headers.get("webhook-signature") || "",
 46→      "webhook-timestamp": req.headers.get("webhook-timestamp") || "",
 47→    };
 48→
 49→    const dodo = new DodoPayments({
 50→      bearerToken: DODO_API_KEY,
 51→      webhookKey: WEBHOOK_KEY,
 52→    });
 53→
 54→    let unwrapped: any;
 55→    try {
 56→      unwrapped = dodo.webhooks.unwrap(rawBody, { headers: webhookHeaders });
 57→    } catch (e) {
 58→      console.error("Invalid webhook signature", e);
 59→      await logSystemError({
 60→        function_name: "dodo-webhook",
 61→        error_type: "WEBHOOK_VALIDATION",
 62→        severity: "critical",
 63→        error_message: errorToMessage(e),
 64→        error_stack: errorToStack(e),
 65→      });
