153→            .single();
154→
155→          if (profile) {
156→            await supabase
157→              .from("profiles")
158→              .update({
159→                [creditField]: ((profile as any)[creditField] ?? 0) + paymentRow.credits_purchased,
160→                credits: (profile.credits ?? 0) + paymentRow.credits_purchased,
161→              })
162→              .eq("user_id", paymentRow.user_id);
163→          }
