 5→const ChatWidget = () => {
 6→  const { data } = useQuery({
 7→    queryKey: ["chat_widget_config"],
 8→    queryFn: async () => {
 9→      const { data, error } = await supabase
10→        .from("platform_config")
11→        .select("chat_widget_enabled, chat_widget_code")
12→        .limit(1)
13→        .single();
14→      if (error) return null;
15→      return data as { chat_widget_enabled: boolean; chat_widget_code: string } | null;
16→    },
17→    staleTime: 5 * 60 * 1000,
18→  });
19→
20→  useEffect(() => {
21→    const containerId = "rankora-chat-widget";
22→
23→    // Clean up any previous widget
24→    const existing = document.getElementById(containerId);
25→    if (existing) existing.remove();
26→
27→    if (!data?.chat_widget_enabled || !data?.chat_widget_code?.trim()) return;
28→
29→    // Create a container and inject the embed code
30→    const container = document.createElement("div");
31→    container.id = containerId;
32→    document.body.appendChild(container);
33→
34→    // Parse and execute scripts from the embed code
35→    const temp = document.createElement("div");
36→    temp.innerHTML = data.chat_widget_code;
37→
38→    // Move non-script nodes
39→    Array.from(temp.childNodes).forEach((node) => {
40→      if (node instanceof HTMLScriptElement) {
41→        const script = document.createElement("script");
42→        // Copy attributes
43→        Array.from(node.attributes).forEach((attr) =>
44→          script.setAttribute(attr.name, attr.value)
45→        );
46→        script.textContent = node.textContent;
47→        container.appendChild(script);
48→      } else {
49→        container.appendChild(node.cloneNode(true));
50→      }
51→    });
52→
53→    return () => {
54→      const el = document.getElementById(containerId);
55→      if (el) el.remove();
56→    };
57→  }, [data?.chat_widget_enabled, data?.chat_widget_code]);
58→
59→  return null;
60→};
61→
62→export default ChatWidget;
