193→function parseDate(dateStr: string, currentYear: number, currentMonth: number): number {
194→  if (!dateStr) return 0;
195→  const s = dateStr.trim();
196→
197→  // Try "YYYY-MM" or "MM/YYYY" or "YYYY"
198→  const ymd = s.match(/^(\d{4})[\/\-](\d{1,2})/);
199→  if (ymd) return parseInt(ymd[1]) + (parseInt(ymd[2]) - 1) / 12;
200→
201→  const mdy = s.match(/^(\d{1,2})[\/\-](\d{4})/);
202→  if (mdy) return parseInt(mdy[2]) + (parseInt(mdy[1]) - 1) / 12;
203→
204→  // "Jan 2020", "January 2020"
205→  const monthYear = s.match(/^([a-zA-Z]+)\s+(\d{4})/);
206→  if (monthYear) {
207→    const month = monthNameToNum(monthYear[1]);
208→    if (month > 0) return parseInt(monthYear[2]) + (month - 1) / 12;
209→  }
210→
211→  // Plain year "2020"
212→  const plainYear = s.match(/^(\d{4})$/);
213→  if (plainYear) return parseInt(plainYear[1]);
214→
215→  return 0;
216→}
