16→-- Update deduct_credits to use all three credit buckets:
17→-- subscription_credits (first) → topup_credits (second) → bonus_credits (third)
18→CREATE OR REPLACE FUNCTION public.deduct_credits(_user_id uuid, _job_id uuid, _amount integer)
19→ RETURNS boolean
20→ LANGUAGE plpgsql
21→ SECURITY DEFINER
22→ SET search_path TO 'public'
23→AS $$
24→DECLARE
25→  sub_c   INTEGER;
26→  top_c   INTEGER;
27→  bon_c   INTEGER;
28→  remaining INTEGER;
29→  from_sub INTEGER;
30→  from_top INTEGER;
31→  from_bon INTEGER;
32→BEGIN
33→  SELECT subscription_credits, topup_credits, bonus_credits
34→    INTO sub_c, top_c, bon_c
35→    FROM public.profiles
36→    WHERE user_id = _user_id
37→    FOR UPDATE;
38→
39→  IF COALESCE(sub_c, 0) + COALESCE(top_c, 0) + COALESCE(bon_c, 0) < _amount THEN
40→    RETURN FALSE;
41→  END IF;
42→
43→  remaining := _amount;
44→
45→  -- Deduct from subscription credits first
46→  from_sub := LEAST(COALESCE(sub_c, 0), remaining);
47→  remaining := remaining - from_sub;
48→
49→  -- Then from topup credits
50→  from_top := LEAST(COALESCE(top_c, 0), remaining);
51→  remaining := remaining - from_top;
52→
53→  -- Then from bonus credits
54→  from_bon := LEAST(COALESCE(bon_c, 0), remaining);
55→
56→  UPDATE public.profiles
57→    SET subscription_credits = subscription_credits - from_sub,
58→        topup_credits        = topup_credits - from_top,
59→        bonus_credits        = bonus_credits - from_bon,
60→        credits              = credits - _amount,
61→        updated_at           = now()
62→    WHERE user_id = _user_id;
63→
64→  INSERT INTO public.usage_logs (user_id, job_id, credits_used)
65→    VALUES (_user_id, _job_id, _amount);
66→
67→  RETURN TRUE;
68→END;
69→$$;
