**Implementation:**
The current `uploadFilesFromSnapshot` loops sequentially and throws on first failure. If file 3 of 5 fails, files 1-2 are uploaded but the job errors out.

Refactor to:
1. Track successfully uploaded resume IDs
2. On failure, continue uploading remaining files (best-effort)
3. If at least one file uploaded successfully, proceed to ranking with those
4. Report partial failure to user via toast

```typescript
const uploadFilesFromSnapshot = async (jobId: string, filesToUpload: UploadedFile[]): Promise<string[]> => {
  if (!user) return [];
  const resumeIds: string[] = [];
  const failures: string[] = [];

  for (const { file, name } of filesToUpload) {
    try {
      const filePath = `${user.id}/${jobId}/${Date.now()}_${name}`;
      const { error: uploadError } = await supabase.storage.from("resumes").upload(filePath, file);
      if (uploadError) throw uploadError;
      const { data: resume, error: resumeError } = await supabase
        .from("resumes")
        .insert({ job_id: jobId, filename: name, file_path: filePath })
        .select("id")
        .single();
      if (resumeError || !resume) throw resumeError || new Error("Failed to save resume");
      resumeIds.push(resume.id);
    } catch (err) {
      console.error(`Upload failed for ${name}:`, err);
      failures.push(name);
    }
  }

  if (failures.length > 0) {
    toast.warning(`${failures.length} file(s) failed to upload: ${failures.join(", ")}`);
  }
  if (resumeIds.length === 0) throw new Error("All uploads failed");
  return resumeIds;
};
```

